import math

def classify_triangle_by_sides(p1, p2, p3):
    def distance(p, q):
        return math.hypot(p[0] - q[0], p[1] - q[1])

    a = distance(p1, p2)
    b = distance(p2, p3)
    c = distance(p3, p1)

    if a == b == c:
        return 'equilateral'
    elif a == b or b == c or a == c:
        return 'isosceles'
    else:
        return 'scalene'
