def is_convex_polygon(points):
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    prev = 0
    for i in range(n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        curr = cross_product(o, a, b)
        if curr == 0:
            return False
        if prev * curr < 0:
            return False
        prev = curr

    return True
