    def rotate90(grid):
        n = len(grid)
        m = len(grid[0])
        return [[grid[n - j - 1][i] for j in range(n)] for i in range(m)]

    def rotate180(grid):
        return rotate90(rotate90(grid))

    def rotate270(grid):
        return rotate90(rotate180(grid))

    if grid1 == grid2:
        return True
    if rotate90(grid1) == grid2:
        return True
    if rotate180(grid1) == grid2:
        return True
    if rotate270(grid1) == grid2:
