import math

def classify_triangle_by_sides(p1, p2, p3):
    def distance(p, q):
        return math.sqrt((p[0] - q[0])**2 + (p[1] - q[1])**2)

    d1 = distance(p1, p2)
    d2 = distance(p2, p3)
    d3 = distance(p3, p1)

    if d1 == d2 == d3:
        return 'equilateral'
    elif d1 == d2 or d2 == d3 or d3 == d1:
        return 'isosceles'
    else:
        return 'scalene'
