def is_convex_polygon(points):
    def cross_product(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    n = len(points)
    if n < 3:
        return False

    previous = 0
    for i in range(n):
        current = cross_product(points[i], points[(i+1)%n], points[(i+2)%n])
        if current == 0:
            return False
        if previous * current < 0:
            return False
        previous = current
    return True
