def equal_under_rotation(grid1, grid2):
    # Function to rotate a grid 90 degrees clockwise
    def rotate(grid):
        return [list(row)[::-1] for row in zip(*grid)]

    # Check if two grids are equal
    def are_equal(g1, g2):
        return g1 == g2

    # Check all four possible rotations
    for _ in range(4):
        if are_equal(grid1, grid2):
            return True
        grid1 = rotate(grid1)
    return False
